import { addDays, addMinutes, startOfWeek } from 'date-fns';
import { utcToZonedTime, zonedTimeToUtc } from 'date-fns-tz';
import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { formatDate } from '@dynatrace-sdk/units';

import { useCalendarContext } from './useCalendarContext.js';
import type { _CalendarReducerAction } from '../types/shared-types.js';
import { getDays } from '../utils/helpers.js';

type Weekday = {
  date: Date;
  longName: string;
  shortName: string;
};

/** @internal */
export interface _Day {
  date: Date;
  isCurrentMonthDay: boolean;
}
export interface _SelectDayViewItems {
  weekdays: Weekday[];
  days: _Day[];
  dispatch: React.Dispatch<_CalendarReducerAction>;
}

/** Custom hook used for the day selection view. */
export function useSelectDay(): _SelectDayViewItems {
  const { state, dispatch } = useCalendarContext();

  const intl = useIntl();

  const weekdays = useMemo(() => {
    // Extract the user-settings timezone to use for the calculation
    const configuredTimezone =
      intl.timeZone ?? Intl.DateTimeFormat().resolvedOptions().timeZone;

    // Get a UTC Time of now, then run a startOfDay for the UTC time and
    // convert the given time back to the user time zone.
    const today = utcToZonedTime(
      new Date(),
      configuredTimezone.replace(/UTC/, ''),
    );
    const intervalStart = zonedTimeToUtc(
      startOfWeek(today, { weekStartsOn: state.weekStartsOn }),
      configuredTimezone,
    );

    // eachDayOfInterval was stripping the time and the timeZone completely.
    // For that we now iterate the seven days of the week without the interval.
    const days = [intervalStart];
    for (let i = 1; i < 7; i += 1) {
      // If the timezone offset is different between the days, we need to account for that
      let nextDay = addDays(days[i - 1], 1);

      const previousDayOffset = days[i - 1].getTimezoneOffset();
      const nextDayOffset = nextDay.getTimezoneOffset();
      if (previousDayOffset !== nextDayOffset) {
        nextDay = addMinutes(nextDay, previousDayOffset - nextDayOffset);
      }

      days.push(nextDay);
    }

    return days.map((day) => ({
      date: day,
      longName: formatDate(day, {
        weekday: 'long',
        timeZone: configuredTimezone,
      }),
      shortName: formatDate(day, {
        weekday: 'short',
        timeZone: configuredTimezone,
      }),
    }));
  }, [intl.timeZone, state.weekStartsOn]);

  const days = useMemo(
    () => getDays(state.activeDate, state.weekStartsOn),
    [state.activeDate, state.weekStartsOn],
  );

  return {
    weekdays,
    days,
    dispatch,
  };
}
